SELECT
    ,

FROM course_enrollments course_enrollment
    LEFT JOIN courses_progress course_progress ON course_enrollment.id = course_progress.enrollment_id
WHERE course_enrollment.course_id = #{courseId} AND course_enrollment.user_id = #{userId}

        AND course_enrollment.start_date >= #{startDate}


        AND course_enrollment.end_date <= #{endDate}

SELECT
    ,

FROM course_enrollments course_enrollment
    LEFT JOIN courses_progress course_progress ON course_enrollment.id = course_progress.enrollment_id
    JOIN gc_subject course ON course_enrollment.course_id = course.id AND course.master_id = #{masterId}
WHERE 1=1

        AND course_enrollment.start_date >= #{startDate}


        AND course_enrollment.end_date <= #{endDate}

SELECT
    ,

FROM course_enrollments course_enrollment
    LEFT JOIN courses_progress course_progress ON course_enrollment.id = course_progress.enrollment_id
    JOIN gc_subject course ON course_enrollment.course_id = course.id AND course.master_id = #{masterId}
WHERE course_enrollment.user_id = #{userId}

        AND course_enrollment.start_date >= #{startDate}


        AND course_enrollment.end_date <= #{endDate}
